window.ATLAS_DATA = {"version":2,"date":"2026-10-24","root":{"id":"root","name":"Свои специализированные AI-модели","what":"Обзор основных семейств и подходов. Ветки — разные оси, их можно сочетать; это навигация по области, а не список взаимоисключающих технологий.","children":[{"id":"tasks","name":"Задачи и данные","what":"Начинаем с того, какой результат нужен и какие наблюдения доступны. Одна архитектура может решать много разных задач.","children":[{"id":"classification","name":"Классификация и регрессия","what":"Выбрать класс либо предсказать числовое значение.","tasks":"Брак / норма, тип команды, время операции.","note":"Самый прямой старт для небольшой модели.","lab":"","status":"Основа","sources":[]},{"id":"vision","name":"Компьютерное зрение","what":"Классификация отвечает «что на фото», детекция — «что и где», сегментация — «какие пиксели принадлежат объекту».","tasks":"Контроль деталей, документы и OCR, измерение объектов.","note":"Для каждой задачи нужна своя разметка; кроме CNN применяются Transformer и гибриды.","lab":"","status":"Практика","sources":[]},{"id":"text","name":"Текст и язык","what":"Классификация, извлечение сущностей, поиск, перевод, суммаризация и генерация — разные задачи.","tasks":"Команда → действие; сообщение → поля; поиск похожих документов.","note":"Для выбора одной из команд часто достаточно классификатора, без генеративной LLM.","lab":"","status":"Практика","sources":[]},{"id":"audio","name":"Звук и речь","what":"Работа с волной или её временно-частотным представлением.","tasks":"Ключевое слово, акустический дефект, распознавание речи, синтез.","note":"Распознать несколько звуков заметно проще, чем построить универсальную речь.","lab":"","status":"Практика","sources":[]},{"id":"timeseries","name":"Временные ряды и сигналы","what":"Учитываем порядок, шаг времени, сезонность и задержки.","tasks":"Прогноз, телеметрия, вибрации, изменение режима.","note":"Разделяем train/test по времени или независимым сессиям, а не случайным соседним окнам.","lab":"","status":"Практика","sources":[]},{"id":"graphsdata","name":"Графы, геометрия и 3D","what":"Данные могут иметь связи, координаты, симметрии, структуру множества.","tasks":"Зависимости компонентов, молекулы, облака точек, CAD.","note":"Структура данных определяет полезные ограничения модели.","lab":"","status":"Практика","sources":[]},{"id":"recommend","name":"Поиск, ранжирование, рекомендации","what":"Оценить похожесть или упорядочить кандидатов.","tasks":"Дубликаты, подбор детали, рекомендации, приоритет результатов.","note":"Сравниваем с простым текстовым поиском и матричной факторизацией.","lab":"","status":"Практика","sources":[]},{"id":"anomaly","name":"Аномалии и редкие события","what":"Найти отклонения от нормы; иногда заранее известны примеры дефектов.","tasks":"Необычные логи, сбои оборудования, дефекты.","note":"Редкость сама по себе не означает ошибку. Главные вопросы — ложные тревоги и пропущенные события.","lab":"","status":"Практика","sources":[]},{"id":"multimodal","name":"Мультимодальность","what":"Объединение нескольких типов данных в одной задаче.","tasks":"Фото + текст, звук + видео, датчики + журнал операций.","note":"Начать можно с объединения двух готовых векторов признаков, а не с огромной общей модели.","lab":"","status":"Практика","sources":[]},{"id":"controltask","name":"Действия, планирование и моделирование","what":"Выбирать последовательность действий, прогнозировать последствия, искать допустимое решение.","tasks":"Игры, управление, расписания, симуляции.","note":"Оптимизатор или поиск иногда решает задачу лучше обучения; сравнение входит в эксперимент.","lab":"","status":"Практика","sources":[]}],"sources":[]},{"id":"models","name":"Семейства моделей","what":"Выбираем математическую конструкцию. Архитектуры, генеративные схемы и гибриды могут сочетаться.","children":[{"id":"classic","name":"Классическое ML","what":"Часто самые экономные и полезные модели для небольших данных; актуальная база для сравнения с нейросетями.","children":[{"id":"linear","name":"Линейные модели","short":"Прогноз числа или класса","full":"Linear / Logistic Regression","what":"Взвешивают входные признаки. Линейная регрессия предсказывает число, логистическая — вероятность класса.","tasks":"Расход материала, категория заявки, спам, намерение команды по текстовым признакам.","lab":"TF-IDF + логистическая регрессия: текст команды → одно из 10 действий.","note":"Хорошая первая точка сравнения. Это машинное обучение; нейросеть для такой задачи может не понадобиться.","sources":["sklearn"],"status":"Практика"},{"id":"trees","name":"Деревья и бустинг","short":"Табличные данные","full":"Decision Tree / Random Forest / Gradient Boosting","what":"Дерево задаёт последовательность вопросов о признаках. Лес усредняет деревья, бустинг последовательно исправляет ошибки ансамбля.","tasks":"Прогноз времени операции, расхода, брака или категории по параметрам изделия.","lab":"Предсказать длительность операции по материалу, размерам и станку.","note":"Сильная базовая модель для таблиц. Большой ансамбль тоже может занимать много памяти.","sources":["sklearn"],"status":"Практика"},{"id":"svm","name":"SVM и kernel methods","what":"Разделяющая поверхность с максимальным зазором; ядро позволяет учитывать нелинейные зависимости.","tasks":"Небольшие и средние наборы признаков, тексты, классификация и регрессия.","note":"Ядерные методы могут плохо масштабироваться по числу примеров.","lab":"","status":"Практика","sources":["sklearn"]},{"id":"knn","name":"kNN и методы соседей","what":"Предсказание по похожим обучающим примерам.","tasks":"Простой классификатор, похожие объекты, оценка аномальности.","note":"Обучение почти отсутствует, но хранение примеров и поиск могут быть дорогими.","lab":"","status":"Практика","sources":["sklearn"]},{"id":"naivebayes","name":"Naive Bayes","what":"Вероятностный классификатор с сильным упрощающим предположением об условной независимости признаков.","tasks":"Спам, категории коротких текстов, быстрый baseline.","note":"Быстрый и компактный; предположение не обязано точно выполняться для полезного результата.","lab":"","status":"Практика","sources":["sklearn"]},{"id":"cluster","name":"Кластеризация: k-means, DBSCAN, HDBSCAN","what":"Группирует объекты по выбранному представлению и расстоянию.","tasks":"Группы документов, режимов работы, поиски необычных групп.","note":"Группы не обязательно совпадают с нужными человеку классами.","lab":"","status":"Практика","sources":["sklearn"]},{"id":"decomposition","name":"PCA, NMF, факторизация","what":"Ищет компактное представление признаков или разложение матрицы.","tasks":"Сжатие, подавление шума, скрытые факторы, рекомендации.","note":"Полезная альтернатива автоэнкодеру на малых задачах.","lab":"","status":"Практика","sources":["sklearn"]},{"id":"isolation","name":"Isolation Forest, LOF, One-class SVM","what":"Специализированные способы оценить нетипичность объекта.","tasks":"Аномалии в табличных признаках и телеметрии.","note":"Начальный уровень для детектора аномалий перед AE.","lab":"","status":"Практика","sources":["sklearn"]},{"id":"classicaltime","name":"ARIMA, ETS и классические модели рядов","what":"Используют тренд, сезонность и зависимость от прошлых значений.","tasks":"Спрос, загрузка, временные ряды с устойчивой структурой.","note":"Всегда сравниваем сложную сеть с простыми временными прогнозами.","lab":"","status":"Практика","sources":["sklearn"]}],"sources":["sklearn"]},{"id":"probabilistic","name":"Вероятностные и причинные модели","what":"Не только точечный ответ: неопределённость, скрытые состояния, предположения о причинах.","children":[{"id":"bayes","name":"Байесовские модели и PGM","what":"Объединяют априорные предположения с данными; графические модели описывают зависимости.","tasks":"Малые выборки, иерархические процессы, неопределённость.","note":"Построение адекватной модели важнее формального выбора «байесовской» библиотеки.","lab":"","status":"Практика","sources":["sklearn"]},{"id":"gp","name":"Gaussian Processes","what":"Распределение над функциями, дающее прогноз и оценку неопределённости при своих предположениях.","tasks":"Небольшие экспериментальные данные, калибровка, байесовская оптимизация.","note":"Точная версия плохо масштабируется с числом наблюдений; есть приближения.","lab":"","status":"Практика","sources":["sklearn"]},{"id":"states","name":"HMM, Kalman, state estimation","what":"Моделируют скрытое состояние системы и то, как из него возникают наблюдения.","tasks":"Фильтрация датчиков, слежение, определение режимов.","note":"Сильные и компактные решения, когда динамика системы известна хотя бы приблизительно.","lab":"","status":"Практика","sources":["sklearn"]},{"id":"mixtures","name":"Mixture models, GMM","what":"Описывают данные как смесь нескольких распределений.","tasks":"Кластеры, плотность вероятности, аномалии, скрытые режимы.","note":"Смесь распределений и MoE — родственные идеи распределения ролей, но разные конструкции.","lab":"","status":"Практика","sources":["sklearn"]},{"id":"causal","name":"Causal ML","what":"Изучает эффект вмешательства и причинные зависимости при явных предположениях.","tasks":"Что изменится от настройки процесса или управленческого действия.","note":"Корреляции и нейросеть сами по себе причинность не устанавливают. Нужны дизайн эксперимента или обоснованные допущения.","lab":"","status":"Практика","sources":["sklearn"]}],"sources":["sklearn"]},{"id":"neural","name":"Основные нейросети","what":"ANN — общее название искусственных нейросетей; DNN — сеть с несколькими слоями представлений, а не отдельная архитектура.","children":[{"id":"mlp","name":"MLP","short":"Первая нейросеть","full":"Multilayer Perceptron — многослойный перцептрон","what":"Несколько полносвязных слоёв с нелинейными функциями между ними превращают вектор признаков в предсказание.","tasks":"Классификация и регрессия по числам; простое распознавание цифр.","lab":"Сначала XOR и граница классов; затем распознавание цифр и сравнение с CNN.","note":"Удобный старт для понимания весов, функции потерь, градиента и переобучения.","sources":["pytorch"],"status":"Практика"},{"id":"cnn","name":"CNN","short":"Картинки, звук, сигналы","full":"Convolutional Neural Network — свёрточная сеть","what":"Небольшие обучаемые фильтры ищут локальные шаблоны. Одни и те же фильтры применяются в разных местах входа.","tasks":"Детали на фото, дефекты поверхности, рукописные цифры; 1D-свёртки — сигналы, 2D — изображения и спектрограммы.","lab":"Обучить с нуля компактную CNN на MNIST, затем попробовать свои изображения деталей.","note":"Мой первый выбор для наглядного проекта. Классификация фото, поиск объекта и сегментация — разные задачи и разная разметка.","sources":["pytorch"],"status":"Практика"},{"id":"rnn","name":"RNN","short":"Последовательность и память","full":"Recurrent Neural Network — рекуррентная сеть","what":"Читает элементы по очереди и переносит скрытое состояние между шагами.","tasks":"Небольшие временные ряды, последовательности событий, учебная посимвольная генерация.","lab":"Предсказать следующий символ или следующее значение простого сигнала.","note":"Полезна для понимания памяти модели. Обычная RNN с трудом обучается длинным зависимостям.","sources":["pytorch"],"status":"Практика"},{"id":"lstm","name":"LSTM / GRU","short":"Управляемая память","full":"Long Short-Term Memory / Gated Recurrent Unit","what":"Варианты RNN с механизмами, которые управляют сохранением и забыванием информации.","tasks":"Телеметрия оборудования, последовательности логов, классификация коротких звуков.","lab":"Различать режимы работы по окну измерений датчика.","note":"GRU часто удобна как более простая отправная точка. Сравниваем с прогнозом последнего значения и с TCN.","sources":["pytorch"],"status":"Практика"},{"id":"tcn","name":"TCN","short":"Свёртки по времени","full":"Temporal Convolutional Network","what":"Применяет свёртки к последовательности; причинная версия использует только текущие и прошлые значения.","tasks":"Прогноз временных рядов, анализ вибрации, поиск изменений режима.","lab":"Прогнозировать сигнал и сравнить результат с GRU.","note":"Для прогноза важно не подглядывать в будущее при свёртках, нормализации и разделении данных.","sources":["pytorch"],"status":"Практика"},{"id":"transformer","name":"Transformer","short":"Связи через attention","full":"Transformer — архитектура с механизмом внимания","what":"Attention позволяет элементам учитывать другие элементы контекста. Encoder удобен для представлений, decoder — для последовательной генерации.","tasks":"Намерение текстовой команды, извлечение полей, поиск по смыслу, генерация; также изображения и сигналы.","lab":"Крошечный классификатор команд; позже — учебная посимвольная языковая модель.","note":"Transformer не обязательно LLM. Маленькую учебную модель обучим с нуля; широкий язык обычно выгоднее брать из предобученной модели.","sources":["transformer"],"status":"Практика"},{"id":"gnn","name":"GNN","short":"Объекты и связи","full":"Graph Neural Network — графовая нейросеть","what":"Обновляет представления узлов, обмениваясь информацией по рёбрам графа.","tasks":"Молекулы, связи пользователей, зависимости компонентов, классификация узлов и графов.","lab":"Определять тип узла в небольшом графе зависимостей.","note":"Нужны содержательные связи между объектами. Обычную таблицу не стоит превращать в граф без причины.","sources":["gnn"],"status":"Практика"},{"id":"siamese","name":"Siamese / embeddings","short":"Похожесть объектов","full":"Siamese network — сиамская сеть; embeddings — векторные представления","what":"Один и тот же encoder обрабатывает разные объекты; обучение сближает представления похожих и разделяет непохожие.","tasks":"Дубликаты заявок, похожие детали, семантический поиск, сопоставление названий.","lab":"Находить одинаковые типы деталей по двум изображениям или похожие сообщения.","note":"Это схема построения и обучения: encoder может быть CNN или Transformer. Нужны пары или другой способ задать сходство.","sources":["pytorch"],"status":"Практика"},{"id":"specialblocks","name":"ResNet, U-Net, ViT, equivariant networks","what":"ResNet использует остаточные связи, U-Net — многоуровневое восстановление, ViT — Transformer для изображений; эквивариантные сети учитывают симметрии.","tasks":"Глубокие сети, сегментация, зрение, физика и 3D.","note":"Это конкретные конструкции и ограничения, которые могут сочетаться, а не взаимоисключающие виды AI.","lab":"","status":"Практика","sources":["pytorch"]}],"sources":["pytorch"]},{"id":"modern","name":"Эффективные и альтернативные архитектуры","what":"Активные направления; их выигрыш зависит от задачи, реализации и оборудования.","children":[{"id":"ssm","name":"SSM / S4 / Mamba","what":"Моделируют последовательность через компактное состояние; selective SSM меняют обработку состояния в зависимости от входа.","tasks":"Длинные сигналы, последовательности, языковые и гибридные модели.","note":"Для маленьких опытов годятся; быстрые реализации Mamba часто завязаны на CUDA. Не обещаем такой же выигрыш на Mac.","lab":"","status":"Практика и активные исследования","sources":["mamba"]},{"id":"linearattention","name":"Linear attention, RWKV, гибриды","what":"Семейства подходов к последовательностям с другими компромиссами между памятью состояния, контекстом и вычислениями.","tasks":"Длинный контекст, потоковая обработка, сочетание attention и рекуррентности.","note":"Это несколько разных подходов; линейная сложность не гарантирует лучшего качества или задержки.","lab":"","status":"Практика и активные исследования","sources":["rwkv"]},{"id":"moe","name":"MoE — Mixture of Experts","what":"Маршрутизатор выбирает часть экспертных блоков для конкретного входа.","tasks":"Увеличение ёмкости при ограниченном объёме активных вычислений.","note":"Мало активных параметров не означает мало хранимых весов. Для самой маленькой модели MoE обычно не первый выбор.","lab":"","status":"Практика","sources":[]},{"id":"kan","name":"KAN","what":"В исходной конструкции обучаемые одномерные функции на связях заменяют обычные скалярные веса.","tasks":"Аппроксимация функций, научные данные, поиск интерпретируемых закономерностей.","note":"Интересно сравнить с MLP; универсального преимущества и гарантии меньшего времени нет.","lab":"Восстановить известную формулу по шумным измерениям.","status":"Исследование","sources":["kan"]},{"id":"liquid","name":"Liquid / LTC / CfC / Neural ODE","what":"Семейство моделей с непрерывной динамикой; LTC и CfC — конкретные подходы к динамическому состоянию.","tasks":"Временные сигналы, нерегулярные измерения, управление.","note":"Это не один алгоритм; обучение и численные решатели могут оказаться сложнее GRU.","lab":"Сравнить небольшой CfC и GRU на сигнале.","status":"Специализированная практика и исследования","sources":["liquid"]},{"id":"reservoir","name":"Reservoir Computing / ESN","what":"Динамический резервуар преобразует вход, а в типичном ESN обучается главным образом выходной слой.","tasks":"Быстрое обучение на временных сигналах.","note":"Мало обучаемых параметров не значит мало хранимых состояний или весов резервуара.","lab":"Прогноз сигнала по Echo State Network.","status":"Специализированная практика","sources":["reservoir"]}],"sources":[]},{"id":"generative","name":"Представления и генеративные модели","what":"Как восстанавливать вход, учить скрытое пространство и получать новые примеры.","children":[{"id":"ae","name":"AE","short":"Восстановление входа","full":"Autoencoder — автоэнкодер","what":"Encoder сжимает вход в скрытое представление, decoder пытается восстановить исходные данные.","tasks":"Устранение шума, компактные признаки; иногда поиск аномалий по ошибке восстановления.","lab":"Обучиться на нормальной телеметрии и проверить, выделяет ли ошибка восстановления сбои.","note":"Аномалия не обязана давать большую ошибку. Порог и ложные тревоги проверяем на отдельной выборке.","sources":[],"status":"Практика"},{"id":"vae","name":"VAE","short":"Вероятностное представление","full":"Variational Autoencoder — вариационный автоэнкодер","what":"Учит распределение скрытых переменных; из него можно брать новые значения и генерировать примеры.","tasks":"Генерация простых изображений, изучение скрытого пространства, вероятностные модели данных.","lab":"Генерировать цифры и плавно менять их форму между двумя примерами.","note":"Хороший учебный вход в генеративные модели после обычного AE.","sources":[],"status":"Практика"},{"id":"gan","name":"GAN","short":"Генератор и проверяющий","full":"Generative Adversarial Network — генеративно-состязательная сеть","what":"Генератор создаёт примеры, дискриминатор учится отличать их от настоящих; они обучаются совместно.","tasks":"Синтез изображений и преобразование их внешнего вида.","lab":"Сгенерировать простые изображения цифр небольшой DCGAN.","note":"Обучение может быть нестабильным и давать однообразные результаты. Лучше после освоения обычного цикла обучения.","sources":[],"status":"Практика"},{"id":"diffusion","name":"Diffusion","short":"Генерация через удаление шума","full":"Diffusion model — диффузионная модель","what":"Учится обращать процесс зашумления; новая выборка получается последовательным преобразованием шума.","tasks":"Генерация изображений и звука, восстановление и условная генерация.","lab":"Игрушечная диффузия для двумерных точек; затем небольших картинок.","note":"Это семейство методов, внутри часто работают U-Net или Transformer. Реалистичная генерация требует существенно больше ресурсов.","sources":[],"status":"Практика"},{"id":"autoregression","name":"Autoregressive models","what":"Предсказывают следующий элемент по предыдущим; архитектура может быть Transformer, RNN или другой.","tasks":"Генерация текста, кода, звука и последовательностей.","note":"Обучение next-token и способность надёжно решать задачу — не одно и то же.","lab":"","status":"Практика","sources":[]},{"id":"flows","name":"Normalizing flows","what":"Цепочка обратимых преобразований позволяет моделировать распределение и вычислять плотность в типичных конструкциях.","tasks":"Плотность вероятности, научные данные, генерация и аномалии.","note":"Требования обратимости ограничивают архитектуру; это не то же самое, что flow matching.","lab":"","status":"Практика","sources":[]},{"id":"flowmatching","name":"Flow Matching / Rectified Flow","what":"Обучает поле преобразования между простым исходным и целевым распределением.","tasks":"Генерация изображений, аудио и других данных.","note":"Для обучения принципу достаточно двумерных точек; большое качество требует больших данных и моделей.","lab":"","status":"Практика и активные исследования","sources":["flow"]},{"id":"ebm","name":"Energy-Based Models — EBM","what":"Задают энергию совместимости; подходящие состояния получают меньшую энергию.","tasks":"Структурированные предсказания, ограничения, генеративное моделирование.","note":"Обучение и выборка могут быть трудными; обычно исследовательская ветка.","lab":"","status":"Исследование","sources":[]},{"id":"jepa","name":"JEPA и predictive representations","what":"Предсказывают представление скрытой части наблюдения, а не обязательно её пиксели или токены.","tasks":"Видео, представления мира, восприятие и планирование.","note":"Важен механизм против вырождения представлений. Небольшой опыт возможен, обучение большой world model — другой масштаб.","lab":"","status":"Активные исследования","sources":["jepa"]}],"sources":[]},{"id":"science","name":"Научные, гибридные и необычные модели","what":"Полезны, когда задача имеет физическую, логическую или аппаратную структуру.","children":[{"id":"pinn","name":"PINN — Physics-Informed NN","what":"Добавляет физические уравнения и граничные условия в обучение модели.","tasks":"Прямые и обратные физические задачи, восстановление параметров.","note":"Не универсальная замена численным методам; сравниваем точность и стоимость.","lab":"Восстановить параметры затухающего колебания.","status":"Специализированная практика и исследования","sources":["pinn"]},{"id":"neuraloperator","name":"Neural Operators: FNO / DeepONet","what":"Учат отображения между функциями, например от начальных условий к полю решения.","tasks":"Быстрые приближённые симуляции тепла, течений и других процессов.","note":"Малый учебный пример доступен; научная точность и перенос требуют отдельной проверки.","lab":"","status":"Специализированная практика и исследования","sources":["operator"]},{"id":"symbolic","name":"Символьный AI и программный поиск","what":"Правила, логический вывод, поиск, SAT/SMT, планирование и ограничения.","tasks":"Проверяемые правила, расписания, допустимые действия, доказательства.","note":"Часть методов не обучается по данным; это полноценная соседняя область AI.","lab":"","status":"Практика","sources":[]},{"id":"symbolicreg","name":"Символьная регрессия и neuro-symbolic","what":"Символьная регрессия ищет формулу; нейросимвольные системы сочетают обучаемые компоненты и явную логику.","tasks":"Интерпретируемые зависимости, инженерные правила, обучение с ограничениями.","note":"Проверяем найденную формулу на новых данных и физический смысл.","lab":"Измерения → компактная аналитическая формула.","status":"Специализированная практика и исследования","sources":["pysr"]},{"id":"evolution","name":"Эволюционные методы и neuroevolution","what":"Поиск решений, весов или архитектур через популяцию кандидатов и отбор.","tasks":"Сложные недифференцируемые цели, политики управления, структурный поиск.","note":"Градиенты не обязательны, но много оценок кандидатов может быть дорого.","lab":"","status":"Практика","sources":[]},{"id":"snn","name":"SNN","short":"Импульсы во времени","full":"Spiking Neural Network — импульсная нейросеть","what":"Нейроны накапливают состояние и передают дискретные импульсы во времени.","tasks":"Событийные датчики, нейроморфные вычисления, исследование энергоэффективных систем.","lab":"Распознавание цифр небольшой SNN в симуляторе.","note":"Экономия энергии зависит от оборудования и задачи. На обычном GPU импульсность не гарантирует ускорения.","sources":["snn"],"status":"Исследование"},{"id":"quantum","name":"QNN · Quantum","short":"Параметризованная квантовая схема","full":"Quantum Neural Network — квантовая нейросеть","what":"Использует параметризованные квантовые схемы, измерения и классический оптимизатор для обучения.","tasks":"Исследования квантового ML, небольшие эксперименты классификации и регрессии.","lab":"Два класса на симуляторе нескольких кубитов; сравнение с обычной моделью.","note":"Не обещает практического превосходства. Маленькие опыты возможны на Mac в симуляторе; это отдельная ветка с квантовой математикой.","sources":["quantum"],"status":"Исследование"},{"id":"hdc","name":"Hyperdimensional computing / VSA","what":"Кодирует объекты высокоразмерными векторами и комбинирует их специальными операциями.","tasks":"Компактные классификаторы сигналов, ассоциативная память, символоподобные операции.","note":"Интересно для edge-систем, но эффективность зависит от кодирования и оборудования; отдельная исследовательская ветка.","status":"Специализированная практика и исследования","sources":["hdc"]}],"sources":[]}],"sources":[]},{"id":"training","name":"Способы обучения","what":"Оси комбинируются: например, CNN + self-supervised pretraining + fine-tuning + quantization.","children":[{"id":"signal","name":"Откуда берётся обучающий сигнал","what":"Кто и как задаёт, что модель должна выучить.","children":[{"id":"supervised","name":"Supervised","short":"По правильным ответам","full":"Обучение с учителем","what":"Для входов известны целевые ответы: классы, числа, границы объектов или другой нужный выход.","tasks":"Классификация, регрессия, распознавание и извлечение полей.","lab":"Фото → тип детали; команда → действие.","note":"Качество и разнообразие разметки часто важнее усложнения архитектуры.","sources":[],"status":"Практика"},{"id":"unsupervised","name":"Unsupervised","short":"Структура без меток классов","full":"Обучение без учителя","what":"Ищет структуру в данных без заданных человеком ответов на целевую задачу.","tasks":"Кластеризация, снижение размерности, исследование групп и отклонений.","lab":"Сгруппировать похожие сообщения или измерения; сравнить с k-means и PCA.","note":"Группа похожих объектов сама по себе не получает правильного смыслового названия.","sources":[],"status":"Практика"},{"id":"selfsupervised","name":"Self-supervised","short":"Задание из самих данных","full":"Самоконтролируемое обучение: задача строится из самих данных","what":"Целевой ответ получают из исходных данных: следующий токен, скрытый фрагмент, другая версия того же объекта.","tasks":"Предобучение текста, изображений и звука, изучение полезных представлений.","lab":"Скрыть часть входа и научить модель её восстанавливать.","note":"Обычно рассматривается как часть широкого обучения без ручной разметки. Это не самостоятельный сбор достоверных знаний моделью.","sources":[],"status":"Практика"},{"id":"semisupervised","name":"Semi-supervised / weak supervision","what":"Сочетает размеченные и неразмеченные примеры либо использует неточные автоматические метки.","tasks":"Дорогая ручная разметка, метки из правил, псевдоразметка.","note":"Ошибки псевдометок могут закрепляться. Качественная независимая проверка обязательна.","lab":"","status":"Практика","sources":[]},{"id":"contrastive","name":"Contrastive learning: SimCLR / CLIP-подобные методы","what":"Обучает представления через сравнение подходящих и неподходящих пар.","tasks":"Поиск похожего, связь текста и изображения, признаки без разметки классов.","note":"Выбор пар, отрицательных примеров и аугментаций определяет, что считается похожим.","lab":"","status":"Практика","sources":[]},{"id":"masked","name":"Masked modeling и self-distillation","what":"Восстановление скрытых частей, как в MAE, или согласование представлений учителя и ученика, как в DINO-подобных методах.","tasks":"Предобучение на собственных изображениях, текстах и сигналах.","note":"Не все методы self-supervised требуют отрицательных пар; нужно предотвращать коллапс представлений.","lab":"","status":"Практика","sources":["dino"]}],"sources":[]},{"id":"adaptation","name":"Старт и адаптация","what":"Случайные веса, перенос знаний и быстрое приспособление к новой задаче.","children":[{"id":"scratch","name":"From scratch","short":"Со случайных весов","full":"Обучение модели с нуля","what":"Архитектуру создаём сами и начинаем без предварительно выученных весов.","tasks":"Небольшие MLP, CNN, GRU и учебные Transformer на ограниченных задачах.","lab":"Самостоятельно пройти путь от случайных весов до работающего распознавания цифр.","note":"Учиться с нуля и обучать модель с нуля — разные вещи. Оба режима полезны, но для широкого языка предобучение дорого.","sources":[],"status":"Практика"},{"id":"transfer","name":"Transfer / fine-tuning","short":"Адаптация готовой модели","full":"Transfer learning — перенос обучения; fine-tuning — дообучение","what":"Берём готовые признаки или веса и адаптируем модель к своей задаче; можно обучать только выходную часть или больше слоёв.","tasks":"Свои детали на фото, специализированные тексты, звуковые классы при ограниченном количестве данных.","lab":"Сравнить CNN с нуля и готовый encoder с новым классификатором.","note":"Нужно проверять лицензию, пригодность исходной модели и реальное качество на своих данных.","sources":[],"status":"Практика"},{"id":"lora","name":"LoRA / QLoRA","short":"Экономное дообучение","full":"Low-Rank Adaptation; Quantized LoRA","what":"LoRA обучает небольшие добавочные матрицы при замороженных базовых весах. QLoRA сочетает адаптеры с квантованной основой.","tasks":"Адаптация предобученной языковой модели под узкий формат, стиль или извлечение данных.","lab":"Текст запроса → структурированная команда с параметрами.","note":"Маленький адаптер не заменяет базовую модель. Поддержку конкретного способа обучения на Mac проверим перед выбором стека.","sources":["lora"],"status":"Практика"},{"id":"domain","name":"Domain adaptation / multi-task","what":"Перенос между доменами или обучение нескольким связанным задачам.","tasks":"Другой станок, камера, язык, продукт; совместные классы и регрессия.","note":"Перенос может ухудшить результат, если задачи конфликтуют.","lab":"","status":"Практика","sources":[]},{"id":"meta","name":"Meta-learning / few-shot","what":"Обучение способности адаптироваться по небольшому числу примеров новой задачи.","tasks":"Новые классы с 1–несколькими примерами, семейства похожих задач.","note":"Мало примеров при адаптации не означает мало данных на предварительном обучении.","lab":"","status":"Специализированная практика и исследования","sources":[]},{"id":"icl","name":"In-context learning / foundation models","what":"Предобученная модель использует примеры в контексте без обязательного обновления весов.","tasks":"Классификация по примерам, языковые и табличные foundation models, например TabPFN.","note":"Промпт с примерами — не дообучение весов. Полное предобучение может быть дорогим.","lab":"","status":"Практика","sources":["tabpfn"]},{"id":"preferences","name":"SFT, preference tuning, DPO / RLHF","what":"SFT учит по демонстрациям ответа; preference tuning использует предпочтения между вариантами, RLHF — подкрепление с обратной связью человека.","tasks":"Настройка поведения языковых моделей и политик.","note":"DPO не требует того же RL-цикла, что классическая RLHF. Это продвинутый этап, не замена хорошим данным.","lab":"","status":"Практика","sources":[]}],"sources":[]},{"id":"decision","name":"Подкрепление и принятие решений","what":"Политика учится действовать в среде; сеть — только один из возможных компонентов.","children":[{"id":"bandits","name":"Bandits / contextual bandits","what":"Выбор действия с компромиссом между изучением и использованием лучшего варианта.","tasks":"Подбор варианта, рекомендации, последовательный эксперимент.","note":"Проще полноценного RL: обычно нет моделирования долгой цепочки последствий.","lab":"","status":"Практика","sources":["rl"]},{"id":"rl","name":"RL / DQN","short":"Действия и награда","full":"Reinforcement Learning; Deep Q-Network","what":"Агент действует в среде и учится получать суммарную награду. DQN — один из методов RL, где сеть оценивает полезность действий.","tasks":"Игры, простое управление, последовательное принятие решений.","lab":"Табличное Q-learning в лабиринте, затем DQN с небольшой MLP.","note":"Q-learning не означает квантовое обучение. Нужны среда, награда и много взаимодействий; это сложнее первого классификатора.","sources":["rl"],"status":"Практика"},{"id":"policy","name":"Policy gradients / actor–critic: PPO, SAC","what":"Обучают политику действий, часто вместе с оценкой будущей награды.","tasks":"Игры, непрерывное управление, балансировка, роботы в симуляторе.","note":"Маленькая политика может требовать большого числа взаимодействий со средой.","lab":"","status":"Практика","sources":["rl"]},{"id":"imitation","name":"Imitation / behavior cloning / offline RL","what":"Имитация учится по действиям эксперта; offline RL — по уже собранным траекториям и наградам.","tasks":"Управление без свободного экспериментирования, агент по демонстрациям.","note":"Поведение вне покрытия обучающих траекторий может быть ненадёжным.","lab":"","status":"Практика","sources":["rl"]},{"id":"world","name":"Model-based RL / world models","what":"Учат или используют модель динамики мира и планируют действия с её помощью.","tasks":"Планирование, симуляторы, управление с меньшим количеством реальных опытов.","note":"Ошибка модели мира накапливается при долгом прогнозе. Начать можно с маленького игрового мира.","lab":"","status":"Практика и активные исследования","sources":["rl"]},{"id":"selfplay","name":"Self-play / multi-agent learning","what":"Обучение через игру с собой или взаимодействие нескольких обучаемых агентов.","tasks":"Настольные игры, конкуренция и координация.","note":"Соперники меняются вместе с агентом; оценка и устойчивость обучения усложняются.","lab":"","status":"Практика","sources":["rl"]}],"sources":["rl"]},{"id":"learningprocess","name":"Как организовано обучение","what":"Независимые от архитектуры способы расходовать данные и вычисления.","children":[{"id":"active","name":"Active learning","what":"Модель помогает выбрать следующие примеры для ручной разметки.","tasks":"Экономия времени эксперта, редкие и неоднозначные случаи.","note":"Сначала проверяем, действительно ли отбор даёт больше пользы, чем случайная выборка.","lab":"","status":"Практика","sources":[]},{"id":"continual","name":"Online / continual learning","what":"Последовательное обновление модели при поступлении данных и изменении задач.","tasks":"Дрейф телеметрии, новые категории, изменяющиеся процессы.","note":"Есть риск забыть старые навыки; нужны контроль и иногда воспроизведение старых данных.","lab":"","status":"Практика и активные исследования","sources":[]},{"id":"federated","name":"Federated / privacy-preserving learning","what":"Обучение по распределённым данным; приватность усиливается отдельными механизмами вроде differential privacy.","tasks":"Данные на разных устройствах или в разных организациях.","note":"Федеративность сама по себе не гарантирует приватности.","lab":"","status":"Практика","sources":[]},{"id":"curriculum","name":"Curriculum / augmentation / synthetic data","what":"Порядок сложности, преобразования примеров и синтетика расширяют полезный обучающий сигнал.","tasks":"Мало реальных данных, робастность, редкие сценарии.","note":"Синтетика должна отражать реальную задачу; тест на такой же синтетике может обмануть.","lab":"","status":"Практика","sources":[]},{"id":"automl","name":"AutoML / HPO / NAS","what":"Автоматизированный подбор моделей, гиперпараметров или архитектур в заданном бюджете.","tasks":"Экономия ручного перебора и поиск компромисса качество–ресурсы.","note":"Не исправляет утечку данных и неверную метрику; бюджет поиска учитываем как стоимость обучения.","lab":"","status":"Практика","sources":["automl"]}],"sources":[]}],"sources":[]},{"id":"small","name":"Малые модели и AI-системы","what":"Миниатюрность — характеристика всей системы: веса, runtime, входы, память и данные.","children":[{"id":"size","name":"Уменьшение и ускорение","what":"Измеряем качество, байты весов, пиковую память, задержку и энергию отдельно.","children":[{"id":"compactarch","name":"Компактная архитектура","short":"Меньше вычислений изначально","full":"Небольшая MLP / CNN / Transformer; эффективные блоки","what":"Выбираем достаточное число слоёв и каналов, небольшой вход и подходящий тип модели.","tasks":"Узкий классификатор, распознавание нескольких звуков, работа локально или на устройстве.","lab":"Сокращать число каналов CNN и измерять качество, размер и задержку.","note":"Начальная учебная цель для MLP/CNN: примерно 10 тысяч — 1 миллион параметров, если задача позволяет. Это ориентир, а не гарантия качества.","sources":[],"status":"Практика"},{"id":"distill","name":"Distillation","short":"Большая модель учит маленькую","full":"Knowledge distillation — дистилляция знаний","what":"Компактный ученик учится воспроизводить полезные выходы или представления более сильного учителя.","tasks":"Уменьшение классификатора, encoder или языковой модели для выбранного круга задач.","lab":"Сравнить маленькую CNN с учителем и без него на одном тестовом наборе.","note":"Не гарантирует сохранения всех возможностей учителя. Учитель и его данные тоже имеют стоимость.","sources":["distill"],"status":"Практика"},{"id":"quant","name":"Quantization / QNN","short":"Меньше бит на числа","full":"Quantized Neural Network — квантованная нейросеть","what":"Снижает числовую точность весов и/или активаций. PTQ — после обучения, QAT — обучение с учётом квантования.","tasks":"Уменьшение размера и памяти модели; возможное ускорение на подходящем оборудовании.","lab":"Сравнить одну CNN в FP32 и INT8 на выбранном runtime.","note":"Это не квантовая сеть. INT8 даёт примерно в 4 раза меньше байт на веса против FP32 до служебных данных; скорость и качество надо измерять.","sources":["quant"],"status":"Практика"},{"id":"pruning","name":"Pruning","short":"Удаление частей сети","full":"Pruning — прореживание модели","what":"Убирает отдельные веса, каналы или блоки, после чего часто требуется дообучение.","tasks":"Сокращение избыточных моделей и вычислений.","lab":"Удалить часть каналов CNN и проверить потерю качества и выигрыш времени.","note":"Нули в обычной плотной матрице сами по себе не ускоряют вычисления. Структурное удаление чаще проще использовать на практике.","sources":[],"status":"Практика"},{"id":"factorweights","name":"Low-rank / sparsity / weight sharing","what":"Разложение матриц, разреженность, повторное использование весов и условное вычисление сокращают часть затрат.","tasks":"Компактные слои и вычисление только нужных частей сети.","note":"Математическое сокращение FLOPs не равно ускорению на выбранном runtime.","lab":"","status":"Практика","sources":[]},{"id":"cache","name":"Кэш, batch, compile, efficient attention","what":"Инженерные оптимизации исполнения; кэш переиспользует вычисления, компилятор объединяет операции.","tasks":"Низкая задержка и большая пропускная способность, особенно для последовательностей.","note":"Это не обучение новой модели. KV-cache может занимать больше памяти, чем ожидается по весам.","lab":"","status":"Практика","sources":[]},{"id":"binary","name":"Бинарные и тернарные сети","what":"Крайне низкая разрядность весов и иногда активаций; часто требует специального обучения.","tasks":"Жёстко ограниченная память и специализированное оборудование.","note":"Не просто перевод готовой сети в 1 бит. Качество и реальная скорость зависят от архитектуры и runtime.","status":"Специализированная практика и исследования","sources":["quant"]}],"sources":[]},{"id":"deploy","name":"Где запускать","what":"Оборудование и runtime определяют допустимые операции и реальные ограничения.","children":[{"id":"tinyml","name":"TinyML / Edge AI","short":"Модель на устройстве","full":"Машинное обучение в ограниченной памяти и вычислениях","what":"Область применения: исполнение моделей близко к источнику данных, вплоть до микроконтроллеров.","tasks":"Ключевое слово, простой жест, вибрация, автономный датчик.","lab":"Сначала маленькая модель на Mac; затем экспорт и измерение на конкретном устройстве.","note":"Это не архитектура. Ограничения задаёт устройство: RAM, flash, задержка, питание и доступные операции.","sources":[],"status":"Практика"},{"id":"mac","name":"Mac: CPU, PyTorch MPS, MLX","what":"CPU подходит для классического ML и малых задач; MPS использует GPU через Metal; MLX ориентирован на Apple silicon.","tasks":"Первые эксперименты на M3 Max, обучение небольших сетей и адаптация готовых.","note":"Поддержка операций и конкретных библиотек различается; CUDA-зависимые рецепты нельзя просто перенести на Mac.","lab":"","status":"Практика","sources":["mps","mlx"]},{"id":"export","name":"ONNX / Core ML / встроенные runtime","what":"Экспорт обученной модели в формат и среду исполнения приложения или устройства.","tasks":"Python → приложение на Kotlin, Go, Rust, мобильное устройство или браузер.","note":"Обучение и inference — разные этапы. После экспорта снова проверяем ответы, память и скорость.","lab":"","status":"Практика","sources":[]},{"id":"repro","name":"Версионирование и MLOps","what":"Фиксируем данные, код, конфигурацию, seed, метрики и артефакты эксперимента.","tasks":"Воспроизводимость, сравнение моделей, обновление и мониторинг.","note":"Для учебного проекта достаточно простой дисциплины файлов и команд; тяжёлая платформа не нужна.","lab":"","status":"Практика","sources":[]}],"sources":[]},{"id":"systems","name":"Системы вокруг модели","what":"Соседние подходы, которые часто полезнее увеличения одной нейросети.","children":[{"id":"rag","name":"RAG / retrieval / reranking","what":"Поиск предоставляет модели подходящие внешние сведения, reranker уточняет порядок результатов.","tasks":"Ответы по документации, обновляемые знания, поиск в базе.","note":"RAG сам по себе не обучает веса. Retriever и reranker можно отдельно обучать.","lab":"","status":"Практика","sources":[]},{"id":"agents","name":"Агенты и tool use","what":"Модель выбирает действия или инструменты, а программа исполняет и проверяет их.","tasks":"Узкий помощник, маршрутизация команд, автоматизация.","note":"Агент — организация системы, а не архитектура сети. На первом этапе действия удобно проверять в симуляторе.","lab":"","status":"Практика","sources":[]},{"id":"hybrids","name":"Правила + модель + оптимизатор","what":"Обучаемая оценка сочетается с правилами, поиском или решателем ограничений.","tasks":"Планирование, допустимые операции, проверка структурированного ответа.","note":"Ограничения и проверяемую логику часто проще явно задать программой.","lab":"","status":"Практика","sources":[]},{"id":"kg","name":"Knowledge graphs и структурированная память","what":"Хранят сущности, отношения и факты явно, а не только в весах модели.","tasks":"Связи документов, оборудование, детали, поиск зависимостей.","note":"Граф знаний не обязательно требует GNN; можно использовать обычные запросы и правила.","lab":"","status":"Практика","sources":[]}],"sources":[]}],"sources":[]},{"id":"practice","name":"Фундамент, проверка и выбор пути","what":"Чтобы понимать, почему модель работает, и воспроизводить результат.","children":[{"id":"math","name":"Минимальный математический фундамент","what":"Изучаем по мере экспериментов, без предварительного многолетнего курса.","children":[{"id":"arrays","name":"Векторы, матрицы и тензоры","what":"Формы данных, матричное умножение, размерности и broadcasting.","tasks":"Понять вход, слои, batch и число параметров.","note":"Начнём с небольших числовых примеров.","lab":"","status":"Основа","sources":["pytorch"]},{"id":"derivatives","name":"Производные, градиенты, backprop","what":"Градиент показывает локальное изменение ошибки по параметрам, backprop эффективно вычисляет его.","tasks":"Обучение нейросетей с автоматическим дифференцированием.","note":"Сначала одна производная и цепное правило, затем autograd.","lab":"","status":"Основа","sources":["pytorch"]},{"id":"probability","name":"Вероятность, статистика, информация","what":"Распределения, среднее, дисперсия, likelihood, энтропия, неопределённость.","tasks":"Функции потерь, вероятности классов, оценка экспериментов.","note":"Нужно для понимания качества, а не только для вывода формул.","lab":"","status":"Основа","sources":["pytorch"]},{"id":"optimization","name":"Loss, SGD / Adam, regularization","what":"Оптимизатор меняет веса по функции потерь; регуляризация ограничивает подгонку под тренировочные данные.","tasks":"Любое градиентное обучение; learning rate, weight decay, early stopping.","note":"Уменьшение training loss ещё не доказывает полезность модели.","lab":"","status":"Основа","sources":["pytorch"]}],"sources":["pytorch"]},{"id":"quality","name":"Данные, проверка и надёжность","what":"Эта ветка обязательна независимо от модного названия модели.","children":[{"id":"data","name":"Сбор, разметка, признаки, токенизация","what":"Преобразуем наблюдения в вход и целевой ответ; контролируем дубликаты и качество меток.","tasks":"Таблицы, тексты, картинки, звук и датчики.","note":"Препроцессинг обучаем только на тренировочной части; кодируем в артефакте вместе с моделью.","lab":"","status":"Обязательно","sources":["sklearn"]},{"id":"split","name":"Train / validation / test и утечки","what":"Учимся на train, выбираем настройки по validation, итог оцениваем на отложенном test.","tasks":"Честная проверка обобщения и выбора модели.","note":"Разделяем связанные объекты, пользователей, источники или время; не только строки случайным образом.","lab":"","status":"Обязательно","sources":["sklearn"]},{"id":"metrics","name":"Метрики и baselines","what":"Precision/recall/F1 для классов, MAE/RMSE для чисел, Recall@k/NDCG для поиска; метрика соответствует цене ошибки.","tasks":"Сравнение с правилом, константой, последним значением и простой моделью.","note":"Accuracy на несбалансированных классах может быть бесполезной.","lab":"","status":"Обязательно","sources":["sklearn"]},{"id":"generalization","name":"Переобучение, robustness, OOD, drift","what":"Проверяем данные, отличающиеся от обучающих, устойчивость и изменение условий.","tasks":"Новые камеры, шум, другие пользователи, новые режимы оборудования.","note":"Высокое качество на привычном тесте не гарантирует работу в новых условиях.","lab":"","status":"Обязательно","sources":["sklearn"]},{"id":"uncertainty","name":"Calibration / conformal / abstention","what":"Калибруем вероятности, строим интервалы или разрешаем модели воздержаться.","tasks":"Ответ «не уверен», контроль риска и передача человеку.","note":"Формальные гарантии conformal prediction зависят от предположений о данных.","lab":"","status":"Практика","sources":["sklearn"]},{"id":"explain","name":"Интерпретируемость и анализ ошибок","what":"Изучаем ошибки, вклад признаков, простые объяснения и сравнения при изменении входа.","tasks":"Понять провал модели и улучшить данные.","note":"SHAP, attention-карты и другие объяснения не доказывают причинность.","lab":"","status":"Практика","sources":["sklearn"]}],"sources":["sklearn"]},{"id":"projects","name":"Направления наших подпроектов","what":"Это варианты для выбора, а не уже созданные или обученные проекты.","children":[{"id":"lab-text","name":"Текст → команда / поля","what":"Начать с TF-IDF + линейной модели, сравнить с небольшой сетью, затем encoder или LoRA при необходимости.","tasks":"Узкий помощник для разработчика.","note":"Проверим неизвестные команды, новые формулировки и точность извлечения полей.","lab":"","status":"Можно начать","sources":[]},{"id":"lab-vision","name":"Изображение → класс / дефект","what":"Сравнить MLP и CNN с нуля, затем transfer learning и квантование.","tasks":"Цифры, детали, дефекты.","note":"Самый наглядный путь к пониманию полного цикла нейросети.","lab":"","status":"Можно начать","sources":[]},{"id":"lab-signal","name":"Сигнал → режим / аномалия","what":"Сравнить статистические признаки + деревья, GRU, TCN, AE; позже SSM или ESN.","tasks":"Телеметрия, вибрации, звук оборудования.","note":"Интересный путь к небольшим полезным моделям.","lab":"","status":"Можно начать","sources":[]},{"id":"lab-table","name":"Таблица → прогноз / неопределённость","what":"Сравнить линейную модель, бустинг, MLP и Gaussian Process на подходящем масштабе.","tasks":"Время операции, расход, качество процесса.","note":"Увидим, когда нейросеть вообще оправданна.","lab":"","status":"Можно начать","sources":[]},{"id":"lab-search","name":"Похожие объекты / поиск","what":"Сравнить простое расстояние, текстовый поиск, готовые embeddings и обучение encoder.","tasks":"Дубликаты заявок, похожие детали, документация.","note":"Много практической пользы без генеративной модели.","lab":"","status":"После основ","sources":[]},{"id":"lab-game","name":"Игровой агент / world model","what":"Поиск и табличное Q-learning, затем DQN/PPO и небольшая модель динамики.","tasks":"Лабиринт, простая игра или симулятор.","note":"Больше инженерии среды, чем в обычной классификации.","lab":"","status":"После основ","sources":[]},{"id":"lab-science","name":"Измерения → формула / физическая модель","what":"Сравнить регрессию, Gaussian Process, MLP, KAN, PINN и символьную регрессию на подходящих задачах.","tasks":"Физический процесс и восстановление параметров.","note":"Особенно интересно для инженерных задач; у методов разные предположения.","lab":"","status":"После основ","sources":[]},{"id":"lab-generative","name":"Мини-генератор / представления","what":"AE → VAE, затем маленькая diffusion или flow matching; отдельно masked или contrastive learning.","tasks":"Цифры, простые формы, сигналы.","note":"Начинаем с игрушечного распределения, чтобы видеть сам процесс обучения.","lab":"","status":"После основ","sources":[]}],"sources":[]}],"sources":[]}],"sources":[]},"sources":{"sklearn":["scikit-learn: семейства методов","https://scikit-learn.org/stable/user_guide.html"],"pytorch":["PyTorch: основы обучения","https://docs.pytorch.org/tutorials/beginner/basics/intro.html"],"mps":["Apple: PyTorch на Mac","https://developer.apple.com/metal/pytorch/"],"mlx":["MLX","https://ml-explore.github.io/mlx/build/html/index.html"],"transformer":["Attention Is All You Need","https://arxiv.org/abs/1706.03762"],"mamba":["Mamba / Mamba-2","https://github.com/state-spaces/mamba"],"flow":["Flow Matching","https://github.com/facebookresearch/flow_matching"],"jepa":["V-JEPA 2","https://ai.meta.com/research/vjepa/"],"kan":["Kolmogorov–Arnold Networks","https://arxiv.org/abs/2404.19756"],"liquid":["LTC / CfC / NCP","https://github.com/mlech26l/ncps"],"pinn":["DeepXDE: Scientific ML","https://github.com/lululxvi/deepxde"],"operator":["Neural Operator","https://github.com/neuraloperator/neuraloperator"],"pysr":["PySR: символьная регрессия","https://github.com/astroautomata/PySR"],"rl":["Stable Baselines3: алгоритмы RL","https://stable-baselines3.readthedocs.io/en/master/guide/algos.html"],"tabpfn":["TabPFN","https://github.com/PriorLabs/TabPFN"],"dino":["DINOv2","https://github.com/facebookresearch/dinov2"],"reservoir":["ReservoirPy","https://github.com/reservoirpy/reservoirpy"],"gnn":["PyTorch Geometric","https://pytorch-geometric.readthedocs.io/en/latest/get_started/introduction.html"],"lora":["LoRA: PEFT","https://huggingface.co/docs/peft/main/en/conceptual_guides/lora"],"quant":["Квантование: основы","https://pytorch.org/blog/quantization-in-practice/"],"distill":["Дистилляция: учебный пример","https://docs.pytorch.org/tutorials/beginner/knowledge_distillation_tutorial.html"],"quantum":["Qiskit: Quantum Neural Networks","https://qiskit-community.github.io/qiskit-machine-learning/tutorials/01_neural_networks.html"],"snn":["snnTorch","https://snntorch.readthedocs.io/en/latest/tutorials/index.html"],"automl":["FLAML","https://github.com/microsoft/FLAML"],"rwkv":["RWKV: исходная реализация","https://github.com/BlinkDL/RWKV-LM"],"hdc":["Torchhd: Hyperdimensional Computing","https://torchhd.readthedocs.io/en/stable/"]}};
